// check26.js for climb batch 26, made from plan-25/manifest/check25.js.
// Checks the MANIFEST block of climb batch 26 (gen26.py's output, $OUT26/manifest26.js) spliced into a scratch copy
// of the workflow script, $OUT26/wf-spliced-26.js, and with --write splices it into the tracked script. As
// check25.js: node --check on the original and the spliced copy; both parsed as the body of an async function, as the
// Workflow harness parses them, their export made const; every line outside the block byte-identical; the block
// evaluated with the script's own load checks and scatter order; the batch's rungs (lists26.py's IDS, W, S, L and T, in
// that order, less any that --without names), their fields, no rung bringing a gate step, declaring a checker count,
// a crash or a ladder move, or landing only with another; each section equal to the rung's section 3 of the record
// (backticks dropped, the ellipsis character as three full stops, the minus sign as a hyphen-minus); briefing,
// reasons and checks equal to lists26.py's, one reason per key, checks a sub-list of the briefing; no rung's test the
// stage; no backtick or non-ASCII character in any string the agents read; no text asking a skeptic to see a failure
// again or a stage re-run without a code change (the coordinator skill's references/batch.md, "The workflow"); no
// LEDGER_FROM; the record holding no copy of the block.
// Changed from check25.js: the batch's values (26, CLIMB-BATCH-26.md, lists26.py, $OUT26, manifest26.js); every
// section naming the count stage and the distance stage as stages its rung does not run ("run neither"), and no
// section naming a speed pass or P-148, the intro saying that none makes one, where check25.js asked each section to
// say "no speed pass" (no rung changes the checker: the record's forks 13 and 14); and the briefings against the
// record's section 5, "The briefings, rung by rung": each rung's bullet giving lists26.py's number of keys and of
// checks, and holding each of its reasons, its first letter either case and its full stop dropped, but those of the
// keys lists26.py's OWN_REASONS names, whose reason the record does not give.
// For rung T, added to the record after the Fable review: T, and only T, runs the count stage and the distance stage
// once each on its tree, its section saying "Run the count stage and the distance stage once each", as climb batch
// 25's natives rungs' sections did, and naming a speed pass only to say it makes none; W, S and L keep "run neither". Its last lines say whether the tracked
// script's block equals the generated one, and count the problems.
//   node check26.js [--without <rung>]... [--write] [RECORD]      RECORD defaults to explorations/coordinator/CLIMB-BATCH-26.md
// --without <rung> checks the block that gen26.py writes with the same argument: the batch's rungs less that one.
const fs = require('fs')
const cp = require('child_process')
const path = require('path')
const ROOT = process.env.FORTRESS_HOME || path.resolve(__dirname, '../../../..')
const HERE = process.env.OUT26 || path.join(ROOT, 'tmp')
const SRC = path.join(ROOT, 'explorations/coordinator/climb-batch-workflow.js')
const argv = process.argv.slice(2)
const WRITE = argv.includes('--write')
const WITHOUT = argv.map((a, i) => argv[i - 1] === '--without' ? a : null).filter(a => a !== null)
const BATCH_NAME = '26'
const idsPy = cp.spawnSync('python3', ['-B', '-c', 'import sys; sys.path.insert(0, sys.argv[1]); from lists26 import IDS; print(",".join(IDS))', __dirname], { encoding: 'utf8' })
if (idsPy.status !== 0) { console.log('lists26.py not read: ' + idsPy.stderr.trim().slice(0, 300)); process.exit(2) }
const ALL_IDS = idsPy.stdout.trim().split(',')
const RUN_IDS = ALL_IDS.filter(x => !WITHOUT.includes(x))
if (WITHOUT.some(x => !ALL_IDS.includes(x))) { console.log('--without names a rung not in the batch'); process.exit(2) }
const STAGE_RUNGS = []
const CHECKER_RUNGS = []
// The rungs that run the count stage and the distance stage once each on their own tree, as climb batch 25's natives
// rungs did: T, whose library edits are text the stages read. Every other rung names both as stages it does not run.
const STAGES_RUNGS = ['T']
const LANDS_ONLY_WITH = Object.fromEntries(ALL_IDS.map(x => [x, []]))
const REC = argv.filter((a, i) => !a.startsWith('--') && argv[i - 1] !== '--without')[0] || path.join(ROOT, 'explorations/coordinator/CLIMB-BATCH-26.md')
const block = fs.readFileSync(path.join(HERE, 'manifest' + BATCH_NAME + '.js'), 'utf8')
const orig = fs.readFileSync(SRC, 'utf8')
let bad = 0
const say = (ok, text) => { if (!ok) bad++; console.log((ok ? 'ok   ' : 'BAD  ') + text) }

function bounds(text) {
  const ls = text.split('\n')
  const m = ls.findIndex(l => l.startsWith('// MANIFEST - the coordinator replaces'))
  if (m < 1 || !/^\/\/ =+$/.test(ls[m - 1])) throw new Error('no rule above the MANIFEST line')
  const e = ls.findIndex(l => l.startsWith('// =========================== END MANIFEST'))
  if (e < m) throw new Error('no END MANIFEST line after the MANIFEST line')
  return { ls, start: m - 1, end: e }
}
const o = bounds(orig)
const pre = o.ls.slice(0, o.start).join('\n'), post = o.ls.slice(o.end).join('\n')
const current = o.ls.slice(o.start, o.end).join('\n') + '\n'
const spliced = pre + '\n' + block + post
const out = path.join(HERE, 'wf-spliced-' + BATCH_NAME + '.js')
fs.writeFileSync(out, spliced)
console.log('the script\'s MANIFEST block is lines ' + (o.start + 1) + ' to ' + o.end + ' of ' + o.ls.length + '; the generated block has ' + block.split('\n').length + ' lines')
say(spliced.startsWith(pre + '\n') && spliced.endsWith(post) && block.endsWith('\n') && !block.split('\n').some(l => l.startsWith('// =========================== END MANIFEST')), 'every line outside the block is byte-identical, and the block ends before END MANIFEST')

for (const f of [SRC, out]) {
  const r = cp.spawnSync('node', ['--check', f], { encoding: 'utf8' })
  say(r.status === 0, 'node --check ' + path.basename(f) + ': exit ' + r.status + (r.status ? ' ' + r.stderr.trim().slice(0, 300) : ''))
}
const AsyncFunction = Object.getPrototypeOf(async function () {}).constructor
for (const [name, text] of [['original', orig], ['spliced', spliced]]) {
  try { new AsyncFunction('args', 'agent', 'pipeline', 'parallel', 'log', 'phase', 'budget', 'workflow', text.replace(/^export const meta/m, 'const meta')); say(true, 'the harness\'s parse: ' + name + ' accepted as an async function body, its export made const') }
  catch (e) { say(false, 'the harness\'s parse: ' + name + ' refused: ' + e.message) }
}

// The block, evaluated with the script's load checks (const LOOKUP_TOOL ... const keysOf) and its scatter line.
const s = bounds(spliced)
const manifest = s.ls.slice(s.start, s.end).join('\n')
const vStart = s.ls.findIndex(l => l.startsWith('const LOOKUP_TOOL = '))
const vEnd = s.ls.findIndex(l => l.startsWith('const keysOf = '))
const validation = s.ls.slice(vStart, vEnd + 1).join('\n')
const scatter = s.ls.find(l => l.startsWith('const SCATTER = '))
let r = null
try {
  r = new Function("const TOOLS = 'explorations/coordinator/tools'\n" + manifest + '\n' + scatter + '\n' + validation +
    '\nreturn { BATCH, BATCH_RECORD, BRIEFING_LISTS, RUNGS, SCATTER, BATCH_INTRO, ledgerFrom: typeof LEDGER_FROM }')()
  say(true, 'the block passes the script\'s own load checks')
} catch (e) { say(false, 'the block fails the script\'s load checks: ' + e.message) }

if (r) {
  const ids = r.RUNGS.map(x => x.id).join(', ')
  const order = r.RUNGS.slice().sort((a, b) => b.expectedMinutes - a.expectedMinutes).map(x => x.id).join('')
  console.log('batch ' + r.BATCH + ', rungs ' + ids + ', scatter ' + r.SCATTER.map(x => x.id).join('') + ', intro ' + r.BATCH_INTRO.length + ' characters')
  say(r.BATCH === BATCH_NAME && r.BATCH_RECORD === 'explorations/coordinator/CLIMB-BATCH-26.md' && r.BRIEFING_LISTS === 'explorations/compile-ladder/plan-26/manifest/lists26.py' && ids === RUN_IDS.join(', ') && r.SCATTER.map(x => x.id).join('') === order, 'batch ' + BATCH_NAME + ', its record and lists, the rungs ' + RUN_IDS.join(', ') + ' and the scatter by expected minutes, ' + order)
  say(r.ledgerFrom === 'undefined', 'no LEDGER_FROM: the gather numbers the new rows through ledger.py')
  say(r.RUNGS.every(x => Array.isArray(x.gateJoins) && !x.gateJoins.length), 'no rung brings a gate step: testSpecData runs from the last landed summary')
  say(r.RUNGS.every(x => JSON.stringify(x.landsOnlyWith || []) === JSON.stringify(LANDS_ONLY_WITH[x.id])), 'no rung lands only with another: ' + r.RUNGS.map(x => x.id + ' [' + (x.landsOnlyWith || []).join(', ') + ']').join(', '))
  say(r.RUNGS.every(x => x.expectedCheckerCrash === undefined && Array.isArray(x.expectedMoves) && !x.expectedMoves.length), 'no rung declares a crash or a ladder move')
  say(r.RUNGS.every(x => x.expectedCheckerCount === undefined), 'no rung declares a checker count: it is reported, never red')

  // The record's section 3, rung by rung, as gen26.py reads it.
  const rec = fs.readFileSync(REC, 'utf8')
  const s3 = rec.slice(rec.indexOf('\n## 3. The rungs\n'), rec.indexOf('\n## 4. '))
  const asAscii = (t) => t.replace(/`/g, '').replace(/…/g, '...').replace(/−/g, '-')
  function section(id) {
    const m = new RegExp('^### ' + id + '\\. .*$', 'm').exec(s3)
    if (!m) return null
    const rest = s3.slice(m.index + m[0].length)
    const nx = rest.search(/^### /m)
    return asAscii((nx < 0 ? rest : rest.slice(0, nx)).replace(/^\n+|\n+$/g, ''))
  }
  // The record's section 5, "The briefings, rung by rung": the bullet of one rung, its backticks dropped.
  const s5b = (() => { const a = rec.indexOf('\n### The briefings, rung by rung\n'); if (a < 0) return ''; const z = rec.indexOf('\n### ', a + 5); return rec.slice(a, z < 0 ? rec.length : z) })()
  function briefingBullet(id) {
    const line = s5b.split('\n').find(l => l.startsWith('- **' + id + '**, '))
    return line ? asAscii(line) : null
  }
  // lists26.py's briefings, reasons and checks, and the keys whose reason is its own.
  const py = cp.spawnSync('python3', ['-B', '-c', 'import json, sys; sys.path.insert(0, sys.argv[1]); from lists26 import LISTS, REASONS, IDS, OWN_REASONS; ' +
    'print(json.dumps({r: {"briefing": LISTS[r][0], "checks": LISTS[r][1], "reasons": [x for _, x in REASONS[r]], "own": OWN_REASONS.get(r, [])} for r in IDS}))', __dirname], { encoding: 'utf8' })
  const lists = py.status === 0 ? JSON.parse(py.stdout) : null
  say(!!lists, 'lists26.py read' + (lists ? '' : ': ' + py.stderr.trim().slice(0, 300)))
  const rerun = /sees? it fail again|re-?run by the skeptic|skeptic re-?runs|run the stage yourself|skeptic rebuilds|re-anchor/i
  for (const x of r.RUNGS) {
    const want = section(x.id)
    say(want !== null && x.section === want, x.id + ': its section is the record\'s section 3 for ' + x.id + ' word for word (' + x.section.length + ' characters)')
    const l = lists && lists[x.id]
    say(!!l && JSON.stringify(x.briefing) === JSON.stringify(l.briefing) && JSON.stringify(x.checks) === JSON.stringify(l.checks) &&
      JSON.stringify(x.reasons) === JSON.stringify(l.reasons.map(asAscii)), x.id + ': briefing ' + x.briefing.length + ' keys, reasons ' + x.reasons.length + ', checks ' + x.checks.length + ', as lists26.py has them')
    say(x.checks.every(k => x.briefing.includes(k)), x.id + ': checks a sub-list of the briefing')
    say(x.branch === 'wip/' + x.slug && /^\/home\/user\/fortress-[a-z0-9-]+$/.test(x.path) && x.expectedMinutes > 0, x.id + ': ' + x.path + ' on ' + x.branch + ', ' + x.expectedMinutes + ' minutes')
    say(Array.isArray(x.pointsToReport) && x.pointsToReport.length > 0 && x.pointsToReport.every(p => typeof p === 'string' && p.trim()), x.id + ': ' + x.pointsToReport.length + ' points to report')
    const texts = [x.title, x.blurb, x.section].concat(x.pointsToReport, x.reasons, x.briefing)
    say(!texts.some(t => /[^\x00-\x7f`]/.test(t) || /`/.test(t)), x.id + ': no backtick or non-ASCII character')
    say(!texts.some(t => rerun.test(t)), x.id + ': nothing asks a skeptic to see a failure again, rebuild, re-run or re-anchor')
    say(x.testIsStage === STAGE_RUNGS.includes(x.id), x.id + ': its test is the stage: ' + x.testIsStage + (STAGE_RUNGS.includes(x.id) ? ', its every edit is library text that only the checker reads differently' : ', a test first'))
    if (STAGES_RUNGS.includes(x.id)) say(/[Rr]un the count stage and the distance stage once each/.test(x.section) && !/run neither/.test(x.section), x.id + ': its section names the count stage and the distance stage as stages it runs once each on its tree')
    else say(/distance stage/.test(x.section) && /count stage/.test(x.section) && /run neither/.test(x.section), x.id + ': its section names the count stage and the distance stage as stages its rung does not run')
    if (CHECKER_RUNGS.includes(x.id)) say(/P-148/.test(x.section) && /speed pass/.test(x.section) && !/no speed pass/.test(x.section), x.id + ': a rung that changes the checker, its section names P-148 and its speed pass')
    else say(!/P-148/.test(x.section) && (STAGES_RUNGS.includes(x.id) ? !/speed pass/.test(x.section.replace(/no speed pass/g, '')) : !/speed pass/.test(x.section)), x.id + ': a rung outside the checker, its section names no speed pass' + (STAGES_RUNGS.includes(x.id) ? ' but to say it makes none' : '') + ' and no P-148')
    // The record's section 5, "The briefings, rung by rung": the rung's bullet, its counts and its reasons.
    const bl = briefingBullet(x.id)
    const cm = bl && /^- \*\*[A-Z]\*\*, ([0-9]+) keys, ([0-9]+) checks: /.exec(bl)
    say(!!cm && +cm[1] === x.briefing.length && +cm[2] === x.checks.length, x.id + ': the record\'s briefing bullet gives ' + (cm ? cm[1] + ' keys and ' + cm[2] + ' checks' : 'no counts') + ', lists26.py ' + x.briefing.length + ' and ' + x.checks.length)
    const marked = bl ? (bl.match(/\(check\)/g) || []).length : -1
    say(marked === x.checks.length, x.id + ': the record marks ' + marked + ' keys (check), lists26.py has ' + x.checks.length + ' checks')
    const own = l ? l.own : []
    const lc = (t) => t.charAt(0).toLowerCase() + t.slice(1)
    const missing = x.briefing.map((k, i) => [k, x.reasons[i]]).filter(([k, why]) => !own.includes(k) && !(bl && (bl.includes(why.replace(/\.$/, '')) || bl.includes(lc(why).replace(/\.$/, '')))))
    say(!!bl && !missing.length, x.id + ': every reason but the ' + own.length + ' of OWN_REASONS is the record\'s' + (missing.length ? '; not in the record: ' + missing.map(([k, why]) => k.slice(0, 60) + ' -> ' + why).join(' | ') : ''))
  }
  say(!/[^\x00-\x7f]|`/.test(r.BATCH_INTRO) && !rerun.test(r.BATCH_INTRO), 'the intro: ASCII, no backtick, no re-run')
  say(/none makes a speed pass|no speed pass/.test(r.BATCH_INTRO) && !/P-148/.test(r.BATCH_INTRO), 'the intro says no rung makes a speed pass, and names no P-148')
  const paths = r.RUNGS.map(x => x.path), slugs = r.RUNGS.map(x => x.slug)
  say(new Set(paths).size === paths.length && new Set(slugs).size === slugs.length, 'every rung has its own worktree and branch')
  say(!rec.includes('const RUNGS') && !rec.includes('_ENTRY = {') && rec.includes('gen26.py') && rec.includes('check26.js'), 'the record names gen26.py and check26.js and holds no copy of the block')
}

const same = current === block
console.log((same ? 'the tracked script\'s block equals the generated one' : 'the tracked script\'s block differs from the generated one') + (WRITE ? '' : '; --write splices it'))
if (WRITE) {
  if (bad) console.log('not written: ' + bad + ' problem(s)')
  else if (same) console.log('nothing to write')
  else { fs.writeFileSync(SRC, spliced); console.log('wrote the block into ' + path.relative(ROOT, SRC)) }
}
console.log('problems: ' + bad)
